static const uint32 kRandoLocationNamesCount = 324;

const char *Rando_GetLocationName(uint16 location_id) {
  for (uint32 i = 0; i < kRandoLocationsCount; i++) {
    if (kRandoLocations[i].id == location_id) {
      if (i < kRandoLocationNamesCount) return kRandoLocationNames[i];
      return "(unnamed)";
    }
  }
  return "(unknown)";
}

uint8 Rando_VanillaItemForRegistryId(uint16 registry_item_id) {
  if (registry_item_id >= kRandoItemGrantMetadataCount) return 0xFF;
  const RandoItemGrantMetadata *m = &kRandoItemGrantMetadata[registry_item_id];
  return m->opcode == kRandoGrantOp_Receive ? (uint8)m->payload : 0xFF;
}

